  Pu = `Ez a vásári esemény a Valve jóváhagyására vár`,
  Fu = `Kérjük, használd a jobb oldali gombot az oldalad felülvizsgálatra beküldéséhez, a kívánt közzétételi dátumod előtt legalább 7 nappal, hogy biztosan legyen idő a felülvizsgálatra, illetve jóváhagyásra és bármilyen szükséges változtatásra.`,
  Iu = `Ha bármilyen változtatásra van szükség az oldaladon, a Steam csapata fel fogja veled venni a kapcsolatot a Steamworks támogatási jegyen keresztül. A jobb oldali gombra kattintva megnézheted a Steamworks támogatási jegyedet, és ha szükséges, megjegyzéseket is fűzhetsz hozzá.`,
  Lu = `Az oldal jóváhagyottként jelölése engedélyezni fogja a partnernek a vásár közzétételét és élőre állítását.`,
  Ru = `Felülvizsgálat kérése...`,
  zu = `Felülvizsgálat kérése`,
  Bu = `Létrehoz egy jegyet a vásári oldal közzétételi jóváhagyásának felülvizsgálati kérelméhez. Akkor tedd ezt, amikor a vásári oldalad tartalmazza a végleges a grafikát és a bemutatni kívánt összes játékot.`,
  Vu = `Ez létrehoz egy Steamworks támogatási jegyet, amely az áruházi oldalad Valve általi felülvizsgálatát kéri. Ezt csak azután szabad megtenni, miután a grafika és szövegek véglegesek, és a játékok listája elkészült.`,
  Hu = `Kérjük, győződj meg róla, hogy az eseményed neve és célja egyértelműen szerepel az oldal tetején. A bemutatókhoz szükség lehet egy szöveges részre az oldalad tetején, amely leírja, mit mutatsz be, és hogyan működik.`,
  Uu = `A felülvizsgálat után a vásári oldal zárolva lesz. Ha a felülvizsgálat vagy az esemény kezdete után változtatásokat kell eszközölnöd, kérjük, add meg a megjegyzésben, hogy mivel járnak ezek a változtatások, és hogy miért nem lehetett azokat megtenni a felülvizsgálat előtt.`,
  Wu = `Opcionális: a felülvizsgálók számára elküldeni kívánt információk.`,
  Gu = `Válassz olyan partnereket, amelyek tagjai szintén hozzá tudnak férni a jegyekhez.`,
  Ku = `Opcionális: Ha ki van választva, a partnerek más tagjai hozzá tudnak férni a jegyekhez, és válaszolni tudnak azokra. Alapesetben csak te tudod olvasni és frissíteni a létrehozott jegyeket, illetve válaszolni azokra.`,
  qu = `Jegy létrehozása sikertelen. Kérjük, próbáld újra később.`,
  Ju = `Nem lehet új jegyet létrehozni; már létezik egy ilyen típusú jegy. Kérjük, fejezd be a másik vásári oldalad felülvizsgálatát, mielőtt ezt beküldenéd, vagy frissítsd a már meglévő jegyet, hogy tartalmazza ennek az oldalnak a felülvizsgálatát is.`,
