  SV = `Nem javasolsz konkrét kategóriát, helyette hagyod, hogy rajongóid válasszák ki azt, amelyik szerintük leginkább illik játékodhoz. Az esemény továbbra is be fog tenni egy hivatkozást a jelölések oldalra.`,
  CV = `Nincs kategória`,
  wV = `Talán a magával ragadó játékmenet, vagy a lebilincselő történet miatt... esetleg a kidolgozott karakterek, a hibátlan megvalósítás vagy az addiktív többjátékos mód eredményeképp. Bármi is legyen az oka, a 2020-as „Év játéka” díj nyertese azonnal klasszikussá vált.`,
  TV = `Az év VR játéka nem bújik a szimpla valóság álcája mögé. Ez a játék javít a valóságon, kihasználja a VR médium lehetőségeit, és feszegeti a virtuális tér határait.`,
  EV = `Ez a játék jó ideje megjelent már. A csapat jócskán maga mögött hagyta kreativitásuk gyermekének bemutatását, de jó szülőkként ezek a fejlesztők tovább gondozzák és támogatják teremtményüket. Ez a játék, ennyi év után is, a mai napig kap új tartalmat.`,
  DV = `Vannak játékok, melyek egyszerűen nem ugyanolyanok, amikor egyedül játszol. Talán szükséged van egy barátra, hogy védje a hátadat. Vagy szükséged van egy barátra, akit hátba szúrhatsz. Így vagy úgy, de jó móka vár azokra, kik barátokat gyűjtenek e játékhoz.`,
  OV = `A grafikai stílusuk nem törekszik való világbeli látványhűségre (ami ugyan maga is nemes cél)… hanem egyedi megjelenést és érzést kelt, amely egy egész játékot áthat.`,
  kV = `E játék fejlesztői a kreatív kísérletezés frontvonalában állnak, friss nézőpontot és észbontó meglepetéseket hozva el. Ez a játék olyan újszerűséggel gyönyörködtetett, inspirált és szórakoztatott, amit játékban korábban még nem láttunk.`,
  AV = `Ez az a játék, amely a kitartást jutalmazza, és nem gyengéknek való. Ez minden idők legkeményebb játéka, amit szerettünk.`,
  jV = `Ez a meg nem énekelt hős megérdemli az elismerést kiemelkedő zenei anyagáért. Ez a legebb zenei anyag! `,
