  EH = `Ez az a játék, amely a kitartást jutalmazza, és nem gyengéknek való. Ez minden idők legkeményebb játéka, amit szerettünk.`,
  DH = `Ez a meg nem énekelt hős megérdemli az elismerést kiemelkedő zenei anyagáért. Ez a legebb zenei anyag! `,
  OH = `Van, amikor csak egy történetgazdag játék jöhet szóba, és ez bizony nagyot üt. Magával ragad, mint bármelyik tévésorozat, és finoman kidolgozott, mint egy minőségi forgatókönyv. Gratulálunk, amiért érzelmeket csal ki belőlünk!`,
