  nU = `Egyenleged:`,
  rU = `%1$s zseton`,
  iU = `Nem sikerült kinyitni a borítékot`,
  aU = `A CSÁSZÁR NAGY VERSENYE`,
  oU = `A kínai horoszkóp eredete`,
  sU = `IV/I. rész`,
  cU = `IV/II. rész`,
  lU = `IV/III. rész`,
  uU = `IV/IV. rész`,
  dU = `A Jáde Császár összehívta birodalma összes teremtményét egy versenyre a mennyei palotáig, kihirdetve, hogy az elsőnek érkező tizenkettő megtiszteltetése egy-egy hely lesz új naptárában.

Az okos Patkány volt az első, aki átkelt a folyón a mennyei tartományba. Nem rajongva az úszásért, Patkány a megbízható Bivaly hátán potyázott, izgatottan ugorva a császár kertjébe, épp mielőtt a páros partot ért volna. 

A szívós Bivaly könnyedén kelt át a folyón. Nem aggódva a verseny végeredményén, Bivaly beletörődött a Patkány sikerében játszott szerepébe.`,
  fU = `A független Tigris túl óvatosan haladt, hogysem megelőzze Bivalyt, gondolván, jobb harmadiknak lenni, mint meg sem érkezni.

A sebes Nyúl gyorsan egy céltalanul sodródó farönkre ugrott. De a szerencse eredményt hozott, ahol a stratégia nem, és segítőkész szél hajtotta biztonságosan a rögtönzött csónakot.

A repülő Sárkány a magasból felfedezett egy bajban levő falut, így persze megállt segíteni, még egy széllökést is ajándékozva Nyúlnak a folyón át. A becsület fontosabb volt a győzelemnél, és Sárkány illőnek találta az ötödik helyet.`,
  pU = `A rejtőzködő Kígyót kevéssé érdekelte a hosszú távú erőfeszítés, így észrevétlenül Ló elülső patája köré tekeredett.

Amint Ló a cél felé vágtázott, Kígyó kitekeredett, épp elég időre ijesztve meg a paripát ahhoz, hogy becsússzon hatodikként, míg az óvakodó Ló szorosan mögötte ügetett.`,
  mU = `Kecske, Majom, és Kakas együttműködtek, de engedték, hogy utazásuk alappillére, Kecske lépjen a nyolcadik helyre. Utána a vidám Majom következett, a peckes Kakas pedig tizedikként futott be, büszkén a sorrend igazságosságára.

A játékos Kutyát főleg a pancsolás érdekelte, úgy érezve, a tizenegyedik hely jó üzlet a sok mókáért cserébe.

Disznó lett az utolsó, aki megállt falatozni és szundítani, elég bölcs lévén, hogy tudja, mindegyik állatnak lesz ideje a császár kegyeit élvezni.`,
