  qfe = `Névtelen képkockaszám-adatok`,
  Jfe = `Ha feliratkozol erre, a játékmeneti képkockaszám-adatok a Steam fiókodhoz kapcsolás nélkül lesznek tárolva, de az általad használt hardvertípus alapján azonosítva lesznek. Ezek az adatok segítenek nekünk többet megtudni a játékkompatibilitásról és javítani a felhasználói élményt a Steamet futtató eszközökön.`,
