  npe = `%1$s%`,
  rpe = `Ezeket az adatokat azért tesszük közzé, mert bár a felhasználók túlnyomó többsége egyetért a játékok Verified besorolásával (>%1$s%), hasznos lehet jobban megérteni azon felhasználók tapasztalatait, akik nem értenek egyet, különösen egy adott játék vagy frissítés kontextusában.`,
