  Vpe = `A diagram szakadékait (pl. %1$s és %2$s FPS között) a VSync okozhatja, amely szinkronizálja a játék képkockaszámát a kijelző frissítési ütemével, hogy elkerülje a kép szakadozását. Emiatt a minták %1$s és %2$s FPS körül csoportosulhatnak, még akkor is, ha a játék átlagos képkockasebessége a kettő közé esik. Ez a VSync várható viselkedése, és bár hatással lehet a képkockák egyenletes megjelenítésére, nem feltétlenül okoz észrevehető akadozást.`,
